      "setup.time": "\u041F\u0435\u0440\u0432\u0430\u044F \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430",
      "setup.timeValue": "\u0417\u0430\u043F\u043B\u0430\u043D\u0438\u0440\u0443\u0439\u0442\u0435 \u043F\u0440\u0438\u043C\u0435\u0440\u043D\u043E {min}\u2013{max} \u043C\u0438\u043D\u0443\u0442 \u0432 \u0437\u0430\u0432\u0438\u0441\u0438\u043C\u043E\u0441\u0442\u0438 \u043E\u0442 \u0441\u0435\u0442\u0438 \u0438 \u043C\u0430\u0448\u0438\u043D\u044B",
